/**
 * world-map.js — the shared base map for every LEEA Geography atlas.
 *
 * One equirectangular world outline, drawn once, reused by every map under
 * public/geography/. Call sites pick the window of the world they want in
 * degrees; this module sets the viewBox, draws the land and the graticule,
 * and hands back a projection so markers land in the right place.
 *
 * Usage:
 *   <script src="/components/world-map.js"></script>
 *   const base = buildWorldMap({
 *     svg: document.querySelector("svg.map"),
 *     lon: [-20, 145],     // west, east edge in degrees
 *     lat: [-8, 62],       // south, north edge in degrees
 *     scale: 8,            // pixels per degree
 *     graticule: { lon: 15, lat: 15 }   // or null for none
 *   });
 *   const [x, y] = base.px(31.0, 27.3);
 *
 * Returns { px, el, svg, width, height, landPath, gratGroup }.
 *
 * The land geometry below is baked in the projection lon0 = -20, lat1 = 62,
 * scale = 8 (the original 古代文明マップ window). buildWorldMap re-projects it
 * onto whatever window the caller asks for with an SVG transform, so the same
 * path serves an Afro-Eurasia crop and a whole-world view alike.
 *
 * Coastline: derived from Natural Earth 1:110m land (public domain), by way of
 * the world-atlas package (ISC, (c) Michael Bostock). Converted once to a flat
 * SVG path by scripts/build-world-map-path.mjs — there is no runtime TopoJSON
 * dependency, and world-atlas is not a package dependency. It covers the whole
 * globe, lon -180..180 and lat -85.6..83.7, so maps that need Antarctica, New
 * Zealand or Patagonia are drawn correctly and not silently cropped.
 */
